import productsData from "@/data/products.json";
import suppliersData from "@/data/suppliers.json";
import sales7dData from "@/data/sales7d.json";
import weather3dData from "@/data/weather3d.json";
import loss30dData from "@/data/loss30d.json";
import coefficientsData from "@/data/coefficients.json";
import { Product, Supplier, SaleRecord, LossRecord, WeatherDay, Coefficients } from "@/types";

export const products: Product[] = productsData;
export const suppliers: Supplier[] = suppliersData;
export const sales7d: SaleRecord[] = sales7dData;
export const weather3d: WeatherDay[] = weather3dData;
export const loss30d: LossRecord[] = loss30dData;
export const coefficients: Coefficients = coefficientsData;

export function getSupplierById(id: string): Supplier | undefined {
  return suppliers.find(s => s.id === id);
}

export function getSalesByProductId(productId: string): number[] {
  const records = sales7d.filter(s => s.productId === productId);
  return records.map(r => r.quantity);
}

export function getLossRateByProductId(productId: string): number {
  const records = loss30d.filter(l => l.productId === productId);
  const sales = getSalesByProductId(productId);
  const totalLoss = records.reduce((sum, r) => sum + r.quantity, 0);
  const totalSales = sales.reduce((sum, s) => sum + s, 0);
  if (totalSales === 0) return 0.03;
  return Math.min(0.2, totalLoss / totalSales);
}

export function getLossTotalByCategory(): Record<string, number> {
  const result: Record<string, number> = {};
  loss30d.forEach(record => {
    const product = products.find(p => p.id === record.productId);
    if (product) {
      result[product.category] = (result[product.category] || 0) + record.quantity * product.price;
    }
  });
  return result;
}

export function getLossByReason(): Record<string, number> {
  const result: Record<string, number> = {};
  loss30d.forEach(record => {
    const product = products.find(p => p.id === record.productId);
    if (product) {
      result[record.reason] = (result[record.reason] || 0) + record.quantity * product.price;
    }
  });
  return result;
}

export function getLossTrend30d(): { date: string; rate: number }[] {
  const dates: Record<string, { loss: number; sales: number }> = {};
  
  for (let i = 29; i >= 0; i--) {
    const date = new Date();
    date.setDate(date.getDate() - i);
    const dateStr = date.toISOString().split("T")[0];
    dates[dateStr] = { loss: 0, sales: 0 };
  }
  
  loss30d.forEach(record => {
    if (dates[record.date]) {
      dates[record.date].loss += record.quantity;
    }
  });
  
  sales7d.forEach(record => {
    if (dates[record.date]) {
      dates[record.date].sales += record.quantity;
    }
  });
  
  return Object.entries(dates).map(([date, data]) => ({
    date,
    rate: data.sales > 0 ? (data.loss / data.sales) * 100 : 0,
  }));
}

export function getTodayWeather(): WeatherDay | undefined {
  const today = new Date().toISOString().split("T")[0];
  return weather3d.find(w => w.date === today);
}

export function getTodayWeekday(): string {
  const days = ["日", "一", "二", "三", "四", "五", "六"];
  return days[new Date().getDay()];
}

export function getHolidayStatus(): "before" | "during" | "normal" {
  const today = new Date();
  const month = today.getMonth() + 1;
  const day = today.getDate();
  
  const holidays = [
    { month: 1, day: 1, name: "元旦" },
    { month: 1, day: 2, name: "元旦" },
    { month: 1, day: 3, name: "元旦" },
    { month: 5, day: 1, name: "劳动节" },
    { month: 5, day: 2, name: "劳动节" },
    { month: 5, day: 3, name: "劳动节" },
    { month: 10, day: 1, name: "国庆" },
    { month: 10, day: 2, name: "国庆" },
    { month: 10, day: 3, name: "国庆" },
    { month: 10, day: 4, name: "国庆" },
    { month: 10, day: 5, name: "国庆" },
    { month: 10, day: 6, name: "国庆" },
    { month: 10, day: 7, name: "国庆" },
  ];
  
  const isHoliday = holidays.some(h => h.month === month && h.day === day);
  if (isHoliday) return "during";
  
  const beforeHoliday = holidays.some(h => {
    const holidayDate = new Date(today.getFullYear(), h.month - 1, h.day);
    const diffDays = Math.ceil((holidayDate.getTime() - today.getTime()) / (1000 * 60 * 60 * 24));
    return diffDays >= 1 && diffDays <= 2;
  });
  if (beforeHoliday) return "before";
  
  return "normal";
}
