import { useEffect, useState } from "react";
import { CloudSun, Calendar, Zap, ShoppingCart, Download } from "lucide-react";
import { useOrderStore } from "@/store/useOrderStore";
import { getTodayWeather, getTodayWeekday, getHolidayStatus, weather3d } from "@/lib/mockData";
import { Order } from "@/types";
import KpiBar from "@/components/KpiBar";
import ProductRow from "@/components/ProductRow";
import AttributionDrawer from "@/components/AttributionDrawer";
import OrderPreviewModal from "@/components/OrderPreviewModal";

const categories = ["全部", "肉类", "水产", "鲜禽", "蔬菜", "水果"];

export default function OrderPage() {
  const {
    products,
    forecasts,
    cart,
    selectedCategory,
    selectedProductId,
    loadForecasts,
    addToCart,
    setSelectedCategory,
    setSelectedProductId,
    generateOrders,
    confirmOrders,
  } = useOrderStore();

  const [previewOrders, setPreviewOrders] = useState<Order[]>([]);
  const [isModalOpen, setIsModalOpen] = useState(false);

  useEffect(() => {
    loadForecasts();
  }, [loadForecasts]);

  const todayWeather = getTodayWeather();
  const weekday = getTodayWeekday();
  const holidayStatus = getHolidayStatus();

  const filteredProducts = selectedCategory === "全部"
    ? products
    : products.filter(p => p.category === selectedCategory);

  const needOrderProducts = filteredProducts.filter(p => forecasts[p.id]?.finalOrder > 0);
  const enoughStockProducts = filteredProducts.filter(p => forecasts[p.id]?.finalOrder === 0);

  const handleQuantityChange = (productId: string, quantity: number) => {
    addToCart(productId, quantity);
  };

  const handleGenerateOrder = () => {
    const orders = generateOrders();
    if (orders.length > 0) {
      setPreviewOrders(orders);
      setIsModalOpen(true);
    }
  };

  const handleConfirmOrders = () => {
    confirmOrders(previewOrders);
    setIsModalOpen(false);
  };

  const cartItemCount = cart.length;

  return (
    <div className="min-h-screen bg-cream">
      <div className="mb-6 flex items-center justify-between">
        <div>
          <div className="flex items-center gap-4 mb-2">
            <h2 className="font-display text-2xl font-bold text-ink">订货建议</h2>
            <span className="px-3 py-1 bg-forest-100 text-forest-700 rounded-full text-sm font-medium">
              智能预测
            </span>
          </div>
          <p className="text-gray-500">
            基于近7日销量、天气、周期等多维度分析，AI自动生成订货建议
          </p>
        </div>
        
        <div className="flex items-center gap-4">
          <div className="flex items-center gap-2 px-4 py-2 bg-white rounded-xl shadow-card">
            <CloudSun className="w-5 h-5 text-blue-500" />
            <span className="text-sm text-gray-600">未来3天天气:</span>
            <div className="flex gap-2">
              {weather3d.slice(0, 3).map((w, i) => (
                <div key={i} className="flex items-center gap-1 px-2 py-1 bg-gray-50 rounded-lg">
                  <span className="text-xs font-medium">{w.weekday}</span>
                  <span className="text-xs text-gray-500">{w.type}</span>
                </div>
              ))}
            </div>
          </div>
          
          <button
            onClick={handleGenerateOrder}
            disabled={cartItemCount === 0}
            className={`flex items-center gap-2 px-6 py-3 rounded-xl font-medium transition-all ${
              cartItemCount > 0
                ? "bg-forest-800 text-white hover:bg-forest-700 shadow-lg shadow-forest-800/20"
                : "bg-gray-200 text-gray-400 cursor-not-allowed"
            }`}
          >
            <ShoppingCart className="w-5 h-5" />
            生成订单 ({cartItemCount})
          </button>
        </div>
      </div>

      <div className="flex items-center gap-2 mb-4">
        {categories.map(cat => (
          <button
            key={cat}
            onClick={() => setSelectedCategory(cat)}
            className={`px-4 py-2 rounded-lg text-sm font-medium transition-all ${
              selectedCategory === cat
                ? "bg-forest-800 text-white"
                : "bg-white text-gray-600 hover:bg-gray-100"
            }`}
          >
            {cat}
          </button>
        ))}
      </div>

      <KpiBar />

      <div className="flex items-center gap-4 mb-4">
        <div className="flex items-center gap-2">
          <Calendar className="w-4 h-4 text-gray-500" />
          <span className="text-sm text-gray-600">今日: 周{weekday}</span>
        </div>
        <div className="flex items-center gap-2">
          <Zap className="w-4 h-4 text-gray-500" />
          <span className={`text-sm ${
            holidayStatus === "before" ? "text-forest-600" :
            holidayStatus === "during" ? "text-ember-600" : "text-gray-600"
          }`}>
            {holidayStatus === "before" ? "节前效应" : holidayStatus === "during" ? "节假日" : "平日"}
          </span>
        </div>
        {todayWeather && (
          <div className="flex items-center gap-2">
            <CloudSun className="w-4 h-4 text-blue-500" />
            <span className="text-sm text-gray-600">{todayWeather.type}</span>
          </div>
        )}
        <button className="ml-auto flex items-center gap-2 px-4 py-2 text-sm text-gray-600 hover:text-forest-700 transition-colors">
          <Download className="w-4 h-4" />
          导出 Excel
        </button>
      </div>

      {needOrderProducts.length > 0 && (
        <div className="mb-6">
          <h3 className="font-display text-lg font-bold text-ink mb-4 flex items-center gap-2">
            <span className="w-2 h-2 bg-ember-500 rounded-full" />
            需要补货 ({needOrderProducts.length})
          </h3>
          <div className="space-y-3">
            {needOrderProducts.map((product) => (
              <ProductRow
                key={product.id}
                product={product}
                forecast={forecasts[product.id]}
                isSelected={selectedProductId === product.id}
                onSelect={() => setSelectedProductId(product.id)}
                onQuantityChange={(qty) => handleQuantityChange(product.id, qty)}
                currentCartQuantity={cart.find(c => c.productId === product.id)?.quantity || 0}
              />
            ))}
          </div>
        </div>
      )}

      {enoughStockProducts.length > 0 && (
        <div>
          <h3 className="font-display text-lg font-bold text-ink mb-4 flex items-center gap-2">
            <span className="w-2 h-2 bg-forest-400 rounded-full" />
            库存充足 ({enoughStockProducts.length})
          </h3>
          <div className="space-y-3">
            {enoughStockProducts.map((product) => (
              <ProductRow
                key={product.id}
                product={product}
                forecast={forecasts[product.id]}
                isSelected={selectedProductId === product.id}
                onSelect={() => setSelectedProductId(product.id)}
                onQuantityChange={(qty) => handleQuantityChange(product.id, qty)}
                currentCartQuantity={cart.find(c => c.productId === product.id)?.quantity || 0}
              />
            ))}
          </div>
        </div>
      )}

      <AttributionDrawer />
      <OrderPreviewModal
        orders={previewOrders}
        isOpen={isModalOpen}
        onClose={() => setIsModalOpen(false)}
        onConfirm={handleConfirmOrders}
      />
    </div>
  );
}
