import { create } from "zustand";
import { Product, Order, ForecastResult } from "@/types";
import { products, getSalesByProductId, getLossRateByProductId, getTodayWeather, getTodayWeekday, getHolidayStatus, coefficients, getSupplierById } from "@/lib/mockData";
import { forecast } from "@/lib/forecast";
import { getStorage, setStorage } from "@/lib/storage";

interface CartItem {
  productId: string;
  quantity: number;
}

interface OrderState {
  products: Product[];
  forecasts: Record<string, ForecastResult>;
  cart: CartItem[];
  orders: Order[];
  selectedCategory: string;
  selectedProductId: string | null;
  loadForecasts: () => void;
  addToCart: (productId: string, quantity: number) => void;
  removeFromCart: (productId: string) => void;
  updateCartQuantity: (productId: string, quantity: number) => void;
  generateOrders: () => Order[];
  confirmOrders: (orders: Order[]) => void;
  setSelectedCategory: (category: string) => void;
  setSelectedProductId: (productId: string | null) => void;
  clearCart: () => void;
}

export const useOrderStore = create<OrderState>((set, get) => ({
  products,
  forecasts: {},
  cart: getStorage("cart", []),
  orders: getStorage("orders", []),
  selectedCategory: "全部",
  selectedProductId: null,

  loadForecasts: () => {
    const forecasts: Record<string, ForecastResult> = {};
    const weather = getTodayWeather();
    const weekday = getTodayWeekday();
    const isHoliday = getHolidayStatus();

    products.forEach(product => {
      const sales7d = getSalesByProductId(product.id);
      const lossRate = getLossRateByProductId(product.id);
      forecasts[product.id] = forecast({
        productId: product.id,
        sales7d,
        currentStock: product.currentStock,
        packSize: product.packSize,
        moq: product.moq,
        weather: weather?.type || "晴",
        weekday,
        isHoliday,
        lossRate,
        coefficients,
      });
    });
    set({ forecasts });
  },

  addToCart: (productId: string, quantity: number) => {
    const cart = get().cart;
    const existing = cart.find(item => item.productId === productId);
    if (existing) {
      existing.quantity = quantity;
    } else {
      cart.push({ productId, quantity });
    }
    set({ cart: [...cart] });
    setStorage("cart", cart);
  },

  removeFromCart: (productId: string) => {
    const cart = get().cart.filter(item => item.productId !== productId);
    set({ cart });
    setStorage("cart", cart);
  },

  updateCartQuantity: (productId: string, quantity: number) => {
    const cart = get().cart.map(item => 
      item.productId === productId ? { ...item, quantity } : item
    );
    set({ cart });
    setStorage("cart", cart);
  },

  generateOrders: () => {
    const { cart, products } = get();
    const ordersBySupplier: Record<string, Order> = {};

    cart.forEach(item => {
      const product = products.find(p => p.id === item.productId);
      if (!product) return;

      const supplier = getSupplierById(product.supplierId);
      if (!supplier) return;

      if (!ordersBySupplier[supplier.id]) {
        ordersBySupplier[supplier.id] = {
          id: `ORD${Date.now()}${supplier.id}`,
          supplierId: supplier.id,
          supplierName: supplier.name,
          items: [],
          totalAmount: 0,
          createdAt: new Date().toISOString(),
        };
      }

      ordersBySupplier[supplier.id].items.push({
        productId: product.id,
        productName: product.name,
        quantity: item.quantity,
        unit: product.unit,
        price: product.price,
        packSize: product.packSize,
      });
      ordersBySupplier[supplier.id].totalAmount += item.quantity * product.price;
    });

    return Object.values(ordersBySupplier);
  },

  confirmOrders: (orders: Order[]) => {
    const currentOrders = get().orders;
    const updatedOrders = [...orders, ...currentOrders];
    set({ orders: updatedOrders, cart: [] });
    setStorage("orders", updatedOrders);
    setStorage("cart", []);
  },

  setSelectedCategory: (category: string) => {
    set({ selectedCategory: category });
  },

  setSelectedProductId: (productId: string | null) => {
    set({ selectedProductId: productId });
  },

  clearCart: () => {
    set({ cart: [] });
    setStorage("cart", []);
  },
}));
