import { AttributionStep, ForecastResult, Coefficients } from "@/types";

interface ForecastInput {
  productId: string;
  sales7d: number[];
  currentStock: number;
  packSize: number;
  moq: number;
  weather: string;
  weekday: string;
  isHoliday: "before" | "during" | "normal";
  lossRate: number;
  coefficients: Coefficients;
}

function calculateMean(values: number[]): number {
  if (values.length === 0) return 0;
  return values.reduce((sum, v) => sum + v, 0) / values.length;
}

function calculateVariance(values: number[], mean: number): number {
  if (values.length === 0) return 0;
  return values.reduce((sum, v) => sum + Math.pow(v - mean, 2), 0) / values.length;
}

function removeOutliers(values: number[]): number[] {
  if (values.length < 3) return values;
  const mean = calculateMean(values);
  const variance = calculateVariance(values, mean);
  const std = Math.sqrt(variance);
  return values.filter(v => Math.abs(v - mean) <= 2 * std);
}

export function forecast(input: ForecastInput): ForecastResult {
  const attribution: AttributionStep[] = [];

  const cleanedSales = removeOutliers(input.sales7d);
  const baseline = Math.round(calculateMean(cleanedSales) * 10) / 10;
  attribution.push({ label: "7日基线均值", value: baseline, note: `已剔除异常值，样本数：${cleanedSales.length}` });

  const weekWeight = input.coefficients.weekWeights[input.weekday] || 1.0;
  const afterWeek = Math.round(baseline * weekWeight * 10) / 10;
  attribution.push({ label: `周期权（周${input.weekday}）`, coefficient: weekWeight, value: afterWeek });

  const weatherCoeff = input.coefficients.weatherCoeff[input.weather] || 1.0;
  const afterWeather = Math.round(afterWeek * weatherCoeff * 10) / 10;
  attribution.push({ label: `天气系数（${input.weather}）`, coefficient: weatherCoeff, value: afterWeather });

  const holidayCoeff = input.coefficients.holidayCoeff[input.isHoliday] || 1.0;
  const afterHoliday = Math.round(afterWeather * holidayCoeff * 10) / 10;
  attribution.push({ label: `节假日系数（${input.isHoliday === "before" ? "节前" : input.isHoliday === "during" ? "节中" : "平日"}）`, coefficient: holidayCoeff, value: afterHoliday });

  let prediction = afterHoliday;
  if (input.coefficients.lossCorrection && input.lossRate > 0) {
    const lossFactor = 1 + input.lossRate;
    prediction = Math.round(prediction * lossFactor * 10) / 10;
    attribution.push({ label: "损耗修正", coefficient: lossFactor, value: prediction, note: `近30天损耗率 ${(input.lossRate * 100).toFixed(1)}%` });
  }

  const safetyStockRatio = input.coefficients.safetyStockRatio || 0.2;
  const safetyStock = Math.round(baseline * safetyStockRatio * 10) / 10;
  attribution.push({ label: "安全库存", coefficient: safetyStockRatio, value: safetyStock });

  const totalNeed = prediction + safetyStock;
  const orderSuggestion = Math.max(0, Math.round((totalNeed - input.currentStock) * 10) / 10);
  attribution.push({ label: "扣减当前库存", value: orderSuggestion, note: `当前库存 ${input.currentStock}` });

  let finalOrder = orderSuggestion;
  if (finalOrder > 0) {
    finalOrder = Math.ceil(finalOrder / input.packSize) * input.packSize;
    attribution.push({ label: `包装规格取整（${input.packSize}${input.productId.startsWith("P") ? "kg" : ""}）`, value: finalOrder });

    if (finalOrder < input.moq) {
      finalOrder = input.moq;
      attribution.push({ label: `MOQ 校验（最低${input.moq}）`, value: finalOrder, note: "已提升至起订量" });
    }
  }

  const mean = calculateMean(input.sales7d);
  const variance = calculateVariance(input.sales7d, mean);
  const cv = mean > 0 ? variance / mean : 0;
  const confidence = Math.max(0.6, Math.min(1, 1 - cv * 0.4));

  return {
    baseline,
    prediction,
    safetyStock,
    orderSuggestion,
    finalOrder,
    attribution,
    confidence,
  };
}
