import { useState } from "react";
import { Plus, Edit, Trash2, Save, X, Info } from "lucide-react";
import { useOrderStore } from "@/store/useOrderStore";
import { getSupplierById, getSalesByProductId, getLossRateByProductId, coefficients } from "@/lib/mockData";
import { Product, Coefficients } from "@/types";

type TabType = "products" | "suppliers" | "coefficients";

interface EditProduct extends Product {
  isEditing?: boolean;
}

export default function ProductManage() {
  const { products, forecasts } = useOrderStore();
  const [activeTab, setActiveTab] = useState<TabType>("products");
  const [editProducts, setEditProducts] = useState<EditProduct[]>(products.map(p => ({ ...p, isEditing: false })));
  const [editCoefficients, setEditCoefficients] = useState<Coefficients>(coefficients);
  const [expandedProduct, setExpandedProduct] = useState<string | null>(null);

  const handleSaveProduct = (productId: string) => {
    setEditProducts(editProducts.map(p => 
      p.id === productId ? { ...p, isEditing: false } : p
    ));
  };

  const handleCancelEdit = (productId: string) => {
    setEditProducts(editProducts.map(p => 
      p.id === productId ? { ...products.find(pr => pr.id === productId)!, isEditing: false } : p
    ));
  };

  const handleUpdateField = (productId: string, field: keyof Product, value: string | number) => {
    setEditProducts(editProducts.map(p => 
      p.id === productId ? { ...p, [field]: value } : p
    ));
  };

  const handleSaveCoefficients = () => {
    console.log("Coefficients saved:", editCoefficients);
  };

  const tabs = [
    { key: "products", label: "商品列表" },
    { key: "suppliers", label: "供应商" },
    { key: "coefficients", label: "系数配置" },
  ] as const;

  const categoryColors: Record<string, string> = {
    "肉类": "bg-red-100 text-red-700",
    "水产": "bg-blue-100 text-blue-700",
    "鲜禽": "bg-orange-100 text-orange-700",
    "蔬菜": "bg-green-100 text-green-700",
    "水果": "bg-yellow-100 text-yellow-700",
  };

  return (
    <div className="min-h-screen bg-cream">
      <div className="mb-6">
        <h2 className="font-display text-2xl font-bold text-ink mb-2">商品管理</h2>
        <p className="text-gray-500">商品信息、供应商规则与预测系数配置</p>
      </div>

      <div className="flex items-center gap-2 mb-6">
        {tabs.map(tab => (
          <button
            key={tab.key}
            onClick={() => setActiveTab(tab.key)}
            className={`px-4 py-2 rounded-lg text-sm font-medium transition-all ${
              activeTab === tab.key
                ? "bg-forest-800 text-white"
                : "bg-white text-gray-600 hover:bg-gray-100"
            }`}
          >
            {tab.label}
          </button>
        ))}
      </div>

      {activeTab === "products" && (
        <div className="bg-white rounded-xl shadow-card overflow-hidden">
          <div className="p-4 border-b border-gray-100 flex items-center justify-between">
            <div className="text-sm text-gray-500">共 {editProducts.length} 个商品</div>
            <button className="flex items-center gap-2 px-4 py-2 bg-forest-800 text-white rounded-lg text-sm font-medium hover:bg-forest-700 transition-colors">
              <Plus className="w-4 h-4" />
              添加商品
            </button>
          </div>

          <div className="overflow-x-auto">
            <table className="w-full">
              <thead>
                <tr className="bg-gray-50">
                  <th className="px-6 py-3 text-left text-xs font-medium text-gray-500 uppercase">商品</th>
                  <th className="px-6 py-3 text-left text-xs font-medium text-gray-500 uppercase">品类</th>
                  <th className="px-6 py-3 text-left text-xs font-medium text-gray-500 uppercase">单价</th>
                  <th className="px-6 py-3 text-left text-xs font-medium text-gray-500 uppercase">包装规格</th>
                  <th className="px-6 py-3 text-left text-xs font-medium text-gray-500 uppercase">MOQ</th>
                  <th className="px-6 py-3 text-left text-xs font-medium text-gray-500 uppercase">当前库存</th>
                  <th className="px-6 py-3 text-left text-xs font-medium text-gray-500 uppercase">供应商</th>
                  <th className="px-6 py-3 text-left text-xs font-medium text-gray-500 uppercase">7日销量</th>
                  <th className="px-6 py-3 text-left text-xs font-medium text-gray-500 uppercase">损耗率</th>
                  <th className="px-6 py-3 text-left text-xs font-medium text-gray-500 uppercase">操作</th>
                </tr>
              </thead>
              <tbody className="divide-y divide-gray-100">
                {editProducts.map(product => {
                  const supplier = getSupplierById(product.supplierId);
                  const sales7d = getSalesByProductId(product.id);
                  const lossRate = getLossRateByProductId(product.id);
                  const forecast = forecasts[product.id];
                  const isExpanded = expandedProduct === product.id;

                  return (
                    <>
                      <tr className="hover:bg-gray-50">
                        <td className="px-6 py-4">
                          <div className="flex items-center gap-3">
                            <span className={`w-8 h-8 rounded-lg flex items-center justify-center text-sm font-bold ${categoryColors[product.category]}`}>
                              {product.category[0]}
                            </span>
                            {product.isEditing ? (
                              <input
                                value={product.name}
                                onChange={(e) => handleUpdateField(product.id, "name", e.target.value)}
                                className="px-2 py-1 border border-gray-300 rounded text-sm"
                              />
                            ) : (
                              <span className="font-medium text-ink">{product.name}</span>
                            )}
                          </div>
                        </td>
                        <td className="px-6 py-4">
                          <span className={`inline-flex px-2 py-1 rounded-full text-xs font-medium ${categoryColors[product.category]}`}>
                            {product.category}
                          </span>
                        </td>
                        <td className="px-6 py-4">
                          {product.isEditing ? (
                            <input
                              type="number"
                              value={product.price}
                              onChange={(e) => handleUpdateField(product.id, "price", parseFloat(e.target.value) || 0)}
                              className="px-2 py-1 border border-gray-300 rounded text-sm w-20"
                            />
                          ) : (
                            <span className="text-forest-700 font-bold">¥{product.price}</span>
                          )}
                        </td>
                        <td className="px-6 py-4">
                          {product.isEditing ? (
                            <input
                              type="number"
                              value={product.packSize}
                              onChange={(e) => handleUpdateField(product.id, "packSize", parseInt(e.target.value) || 1)}
                              className="px-2 py-1 border border-gray-300 rounded text-sm w-20"
                            />
                          ) : (
                            <span className="text-gray-700">{product.packSize}{product.unit}</span>
                          )}
                        </td>
                        <td className="px-6 py-4">
                          {product.isEditing ? (
                            <input
                              type="number"
                              value={product.moq}
                              onChange={(e) => handleUpdateField(product.id, "moq", parseInt(e.target.value) || 1)}
                              className="px-2 py-1 border border-gray-300 rounded text-sm w-20"
                            />
                          ) : (
                            <span className="text-gray-700">{product.moq}{product.unit}</span>
                          )}
                        </td>
                        <td className="px-6 py-4">
                          {product.isEditing ? (
                            <input
                              type="number"
                              value={product.currentStock}
                              onChange={(e) => handleUpdateField(product.id, "currentStock", parseInt(e.target.value) || 0)}
                              className="px-2 py-1 border border-gray-300 rounded text-sm w-20"
                            />
                          ) : (
                            <span className={`font-bold ${
                              product.currentStock < forecast?.baseline * 0.3 ? "text-ember-500" :
                              product.currentStock < forecast?.baseline * 0.6 ? "text-yellow-600" : "text-forest-600"
                            }`}>
                              {product.currentStock}{product.unit}
                            </span>
                          )}
                        </td>
                        <td className="px-6 py-4">
                          <span className="text-gray-700">{supplier?.name || "-"}</span>
                        </td>
                        <td className="px-6 py-4">
                          <span className="text-gray-600">{sales7d.reduce((a, b) => a + b, 0)}{product.unit}</span>
                        </td>
                        <td className="px-6 py-4">
                          <span className={`font-medium ${lossRate > 0.1 ? "text-ember-500" : "text-gray-600"}`}>
                            {(lossRate * 100).toFixed(1)}%
                          </span>
                        </td>
                        <td className="px-6 py-4">
                          <div className="flex items-center gap-2">
                            <button
                              onClick={() => setExpandedProduct(isExpanded ? null : product.id)}
                              className="p-2 text-gray-500 hover:text-forest-600 hover:bg-forest-50 rounded-lg transition-colors"
                              title="查看详情"
                            >
                              <Info className="w-4 h-4" />
                            </button>
                            {product.isEditing ? (
                              <>
                                <button
                                  onClick={() => handleSaveProduct(product.id)}
                                  className="p-2 text-forest-600 hover:bg-forest-50 rounded-lg transition-colors"
                                  title="保存"
                                >
                                  <Save className="w-4 h-4" />
                                </button>
                                <button
                                  onClick={() => handleCancelEdit(product.id)}
                                  className="p-2 text-gray-500 hover:bg-gray-100 rounded-lg transition-colors"
                                  title="取消"
                                >
                                  <X className="w-4 h-4" />
                                </button>
                              </>
                            ) : (
                              <>
                                <button
                                  onClick={() => setEditProducts(editProducts.map(p => 
                                    p.id === product.id ? { ...p, isEditing: true } : p
                                  ))}
                                  className="p-2 text-gray-500 hover:text-blue-600 hover:bg-blue-50 rounded-lg transition-colors"
                                  title="编辑"
                                >
                                  <Edit className="w-4 h-4" />
                                </button>
                                <button className="p-2 text-gray-500 hover:text-ember-600 hover:bg-ember-50 rounded-lg transition-colors" title="删除">
                                  <Trash2 className="w-4 h-4" />
                                </button>
                              </>
                            )}
                          </div>
                        </td>
                      </tr>
                      {isExpanded && (
                        <tr>
                          <td colSpan={10} className="px-6 py-4 bg-gray-50">
                            <div className="grid grid-cols-4 gap-6">
                              <div>
                                <p className="text-xs text-gray-500 mb-1">近7日销量</p>
                                <div className="flex gap-1">
                                  {sales7d.map((qty, i) => (
                                    <div key={i} className="flex-1 bg-forest-100 rounded" style={{ height: `${qty}px`, minHeight: "20px" }} />
                                  ))}
                                </div>
                              </div>
                              <div>
                                <p className="text-xs text-gray-500 mb-1">预测销量</p>
                                <p className="text-2xl font-display font-bold text-forest-700">{forecast?.prediction || "-"}</p>
                                <p className="text-xs text-gray-500">{product.unit}/日</p>
                              </div>
                              <div>
                                <p className="text-xs text-gray-500 mb-1">安全库存</p>
                                <p className="text-2xl font-display font-bold text-forest-700">{forecast?.safetyStock || "-"}</p>
                                <p className="text-xs text-gray-500">{product.unit}</p>
                              </div>
                              <div>
                                <p className="text-xs text-gray-500 mb-1">置信度</p>
                                <p className="text-2xl font-display font-bold text-forest-700">{((forecast?.confidence || 0) * 100).toFixed(0)}%</p>
                                <div className="h-2 bg-gray-200 rounded-full mt-2">
                                  <div className="h-full bg-forest-400 rounded-full" style={{ width: `${(forecast?.confidence || 0) * 100}%` }} />
                                </div>
                              </div>
                            </div>
                          </td>
                        </tr>
                      )}
                    </>
                  );
                })}
              </tbody>
            </table>
          </div>
        </div>
      )}

      {activeTab === "suppliers" && (
        <div className="grid grid-cols-2 gap-4">
          {[
            { id: "S001", name: "鲜达肉业", deliveryCycle: 2, minOrderAmount: 200, leadTime: "T+2", category: "肉类" },
            { id: "S002", name: "海之鲜水产", deliveryCycle: 1, minOrderAmount: 150, leadTime: "T+1", category: "水产" },
            { id: "S003", name: "鲜禽直供", deliveryCycle: 2, minOrderAmount: 180, leadTime: "T+2", category: "鲜禽" },
            { id: "S004", name: "绿源蔬果", deliveryCycle: 1, minOrderAmount: 120, leadTime: "T+1", category: "蔬果" },
          ].map(supplier => (
            <div key={supplier.id} className="bg-white rounded-xl p-5 shadow-card">
              <div className="flex items-center justify-between mb-4">
                <h4 className="font-medium text-ink">{supplier.name}</h4>
                <span className={`px-2 py-1 rounded-full text-xs font-medium ${categoryColors[supplier.category]}`}>
                  {supplier.category}
                </span>
              </div>
              <div className="grid grid-cols-2 gap-4 text-sm">
                <div>
                  <p className="text-gray-500 text-xs">供应商ID</p>
                  <p className="font-medium text-ink">{supplier.id}</p>
                </div>
                <div>
                  <p className="text-gray-500 text-xs">配送周期</p>
                  <p className="font-medium text-ink">{supplier.deliveryCycle}天</p>
                </div>
                <div>
                  <p className="text-gray-500 text-xs">最低起订额</p>
                  <p className="font-medium text-forest-700">¥{supplier.minOrderAmount}</p>
                </div>
                <div>
                  <p className="text-gray-500 text-xs">交货期</p>
                  <p className="font-medium text-ink">{supplier.leadTime}</p>
                </div>
              </div>
            </div>
          ))}
        </div>
      )}

      {activeTab === "coefficients" && (
        <div className="grid grid-cols-2 gap-6">
          <div className="bg-white rounded-xl p-6 shadow-card">
            <h3 className="font-display text-lg font-bold text-ink mb-4">周期权重</h3>
            <div className="space-y-3">
              {Object.entries(editCoefficients.weekWeights).map(([day, weight]) => (
                <div key={day} className="flex items-center justify-between">
                  <span className="text-gray-600">周{day}</span>
                  <div className="flex items-center gap-3">
                    <input
                      type="number"
                      step="0.05"
                      min="0.5"
                      max="2"
                      value={weight}
                      onChange={(e) => setEditCoefficients({
                        ...editCoefficients,
                        weekWeights: { ...editCoefficients.weekWeights, [day]: parseFloat(e.target.value) || 1 }
                      })}
                      className="w-20 px-3 py-2 border border-gray-300 rounded-lg text-sm"
                    />
                    <div className="w-24 h-2 bg-gray-100 rounded-full overflow-hidden">
                      <div className="h-full bg-forest-400" style={{ width: `${weight * 50}%` }} />
                    </div>
                  </div>
                </div>
              ))}
            </div>
          </div>

          <div className="bg-white rounded-xl p-6 shadow-card">
            <h3 className="font-display text-lg font-bold text-ink mb-4">天气系数</h3>
            <div className="space-y-3">
              {Object.entries(editCoefficients.weatherCoeff).map(([weather, coeff]) => (
                <div key={weather} className="flex items-center justify-between">
                  <span className="text-gray-600">{weather}</span>
                  <div className="flex items-center gap-3">
                    <input
                      type="number"
                      step="0.05"
                      min="0.3"
                      max="1.5"
                      value={coeff}
                      onChange={(e) => setEditCoefficients({
                        ...editCoefficients,
                        weatherCoeff: { ...editCoefficients.weatherCoeff, [weather]: parseFloat(e.target.value) || 1 }
                      })}
                      className="w-20 px-3 py-2 border border-gray-300 rounded-lg text-sm"
                    />
                    <div className="w-24 h-2 bg-gray-100 rounded-full overflow-hidden">
                      <div className={`h-full ${coeff >= 1 ? "bg-forest-400" : "bg-ember-400"}`} style={{ width: `${coeff * 60}%` }} />
                    </div>
                  </div>
                </div>
              ))}
            </div>
          </div>

          <div className="bg-white rounded-xl p-6 shadow-card">
            <h3 className="font-display text-lg font-bold text-ink mb-4">节假日系数</h3>
            <div className="space-y-3">
              {Object.entries(editCoefficients.holidayCoeff).map(([status, coeff]) => (
                <div key={status} className="flex items-center justify-between">
                  <span className="text-gray-600">{status}</span>
                  <div className="flex items-center gap-3">
                    <input
                      type="number"
                      step="0.1"
                      min="0.3"
                      max="2"
                      value={coeff}
                      onChange={(e) => setEditCoefficients({
                        ...editCoefficients,
                        holidayCoeff: { ...editCoefficients.holidayCoeff, [status]: parseFloat(e.target.value) || 1 }
                      })}
                      className="w-20 px-3 py-2 border border-gray-300 rounded-lg text-sm"
                    />
                    <div className="w-24 h-2 bg-gray-100 rounded-full overflow-hidden">
                      <div className={`h-full ${coeff >= 1 ? "bg-forest-400" : "bg-ember-400"}`} style={{ width: `${coeff * 50}%` }} />
                    </div>
                  </div>
                </div>
              ))}
            </div>
          </div>

          <div className="bg-white rounded-xl p-6 shadow-card">
            <h3 className="font-display text-lg font-bold text-ink mb-4">其他配置</h3>
            <div className="space-y-4">
              <div className="flex items-center justify-between">
                <span className="text-gray-600">安全库存比例</span>
                <div className="flex items-center gap-3">
                  <input
                    type="number"
                    step="0.05"
                    min="0"
                    max="0.5"
                    value={editCoefficients.safetyStockRatio}
                    onChange={(e) => setEditCoefficients({
                      ...editCoefficients,
                      safetyStockRatio: parseFloat(e.target.value) || 0.2
                    })}
                    className="w-20 px-3 py-2 border border-gray-300 rounded-lg text-sm"
                  />
                  <span className="text-sm text-gray-500">× 基线</span>
                </div>
              </div>
              <div className="flex items-center justify-between">
                <span className="text-gray-600">启用损耗修正</span>
                <button
                  onClick={() => setEditCoefficients({ ...editCoefficients, lossCorrection: !editCoefficients.lossCorrection })}
                  className={`w-12 h-6 rounded-full transition-colors ${
                    editCoefficients.lossCorrection ? "bg-forest-500" : "bg-gray-300"
                  }`}
                >
                  <div className={`w-5 h-5 bg-white rounded-full transition-transform ${
                    editCoefficients.lossCorrection ? "translate-x-6" : "translate-x-0.5"
                  }`} />
                </button>
              </div>
            </div>
            <button
              onClick={handleSaveCoefficients}
              className="w-full mt-6 py-3 bg-forest-800 text-white rounded-xl font-medium hover:bg-forest-700 transition-colors"
            >
              保存配置
            </button>
          </div>
        </div>
      )}
    </div>
  );
}
